(()=>{'use strict';const data=document.querySelector('#db-data');if(!data)return;const t=JSON.parse(data.textContent),u=t.ui,key='editionskompass-databases-1',form=document.querySelector('#db-worksheet'),choices=document.querySelector('#db-choices');let stored={};try{stored=JSON.parse(sessionStorage.getItem(key)||'{}')}catch{stored={};const s=document.querySelector('#db-storage');if(s)s.textContent=u.unavailable}if(!stored||typeof stored!=='object'||Array.isArray(stored))stored={};let answers=stored.answers||{},selection=stored.selection||{};
function save(){try{sessionStorage.setItem(key,JSON.stringify({answers,selection}))}catch{const s=document.querySelector('#db-storage');if(s)s.textContent=u.unavailable}}
if(form){form.addEventListener('submit',e=>e.preventDefault());for(const input of form.querySelectorAll('textarea')){input.value=String(answers[input.name]||'');input.addEventListener('input',()=>{answers[input.name]=input.value;save()})}}
function outcome(){const need=selection.need||'unknown',edit=selection.edit||'git';return edit==='db'?'C':need==='unknown'?'unknown':need==='files'?'A':'B'}
function result(){const root=document.querySelector('#db-result');if(!root)return;root.replaceChildren();const [title,action]=t.outcomes[outcome()];for(const [tag,text]of[['h3',u.recommendation+': '+title],['p',action]]){const el=document.createElement(tag);el.textContent=text;root.append(el)}if(outcome()!=='A'&&selection.support!=='yes'){const el=document.createElement('p');el.className='db-warning';el.textContent=t.support_warning;root.append(el)}const el=document.createElement('p');el.textContent=selection.public==='yes'?t.public_warning:t.no_public;root.append(el)}
if(choices){choices.addEventListener('submit',e=>e.preventDefault());for(const input of choices.querySelectorAll('select')){if([...input.options].some(o=>o.value===selection[input.name]))input.value=selection[input.name];selection[input.name]=input.value;input.addEventListener('change',()=>{selection[input.name]=input.value;save();result()})}result()}
const buttons=[...document.querySelectorAll('.db-model-button')];function model(id){for(const b of buttons)b.setAttribute('aria-pressed',String(b.dataset.model===id));for(const panel of document.querySelectorAll('.db-model-panel'))panel.hidden=panel.id!=='db-model-'+id}for(const b of buttons)b.addEventListener('click',()=>model(b.dataset.model));if(buttons.length)model('A');
document.querySelector('#db-clear')?.addEventListener('click',()=>{answers={};selection={};try{sessionStorage.removeItem(key)}catch{}for(const x of form.querySelectorAll('textarea'))x.value='';if(choices)for(const x of choices.querySelectorAll('select')){x.selectedIndex=0;selection[x.name]=x.value}result();document.querySelector('#db-message').textContent=u.reset});
document.querySelector('#db-export')?.addEventListener('click',()=>{const lines=['# '+t.worksheet_title,'','Editionskompass · 1.0 · 2026-10-28',''];if(choices){lines.push('## '+u.recommendation,t.outcomes[outcome()][0],t.outcomes[outcome()][1],'');for(const [id,label,options]of t.questions)lines.push(label+': '+(options.find(x=>x[0]===selection[id])?.[1]||''),'')}for(const [id,label]of t.fields)lines.push('## '+label,answers[id]||'…','');const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='git-databases-'+document.documentElement.lang+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
for(const b of document.querySelectorAll('[data-db-print]'))b.addEventListener('click',()=>window.print());window.addEventListener('beforeprint',()=>{for(const d of document.querySelectorAll('.db-document details')){d.dataset.wasOpen=String(d.open);d.open=true}for(const input of document.querySelectorAll('.db-field textarea')){let out=input.parentElement.querySelector('.db-print-answer');if(!out){out=document.createElement('p');out.className='db-print-answer';input.after(out)}out.textContent=input.value||'________________________________________________'}});window.addEventListener('afterprint',()=>{for(const d of document.querySelectorAll('details[data-was-open]')){d.open=d.dataset.wasOpen==='true';delete d.dataset.wasOpen}});
})();
